// Painel admin — métricas e plano de implementações.
const adminEl = () => document.getElementById("admin");
const fmt = n => (n == null ? "0" : Number(n).toLocaleString("pt-BR"));
// Escapa &, <, > E TAMBÉM aspas — era o único helper de escape do projeto que não escapava `"`
// (app.js, diario.js e conta.js sempre escaparam). Com a f23 o valor passou a ir dentro de
// value="…" de um input e a voltar para o banco: um título com aspas (`Guia: "fissuras"`) fechava
// o atributo e o campo era GRAVADO truncado, em silêncio. Escapar aspas é inócuo no uso em texto.
const escA = s => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

// ── Tab switching ──────────────────────────────────────────────────────────
function showAdminView(v) {
  if (v === "metricas") renderAdmin();
  else if (v === "marketing") renderMarketing();
  else if (v === "feedback") renderFeedback();
  else if (v === "suporte") renderSuporte();
  else if (v === "financeiro") renderFinanceiro();
  else if (v === "repositorio") renderRepositorio();
  else if (v === "integracoes") renderIntegracoes();
  else if (v === "saude") renderSaude();
  else if (v === "baseia") renderBaseIA();
  else if (v === "seguranca") renderSeguranca();
  else if (v === "plano") renderPlano();
  else if (v === "viabilidade") renderViabilidade();
}

function setActiveTab(v) {
  document.querySelectorAll("#admin-nav .adm-tab").forEach(b => b.classList.toggle("active", b.dataset.view === v));
}

// ── Feedback / voz do cliente (e13) ─────────────────────────────────────────
async function renderFeedback() {
  setActiveTab("feedback");
  const el = adminEl();
  el.classList.remove("adm-body--embed");
  el.innerHTML = `<p class="page-sub">Carregando feedback…</p>`;
  if (typeof FB === "undefined" || !window.supa) { el.innerHTML = `<p class="page-sub">Backend indisponível.</p>`; return; }
  const filtro = renderFeedback._filtro || {};
  const nps = await FB.npsResumo().catch(() => ({ respostas: 0, nps: null }));
  let itens = [], listaErro = null;
  try { itens = await FB.listar(filtro); } catch (e) { listaErro = e.message || e; }
  // e31: quem enviou — nome/e-mail via RPC admin (0079); sem ela, o user_id curto já rastreia
  const autores = await FB.autores(itens.map(i => i.user_id));
  {
    const cont = { novo: 0, em_analise: 0, planejado: 0, concluido: 0 };
    itens.forEach(i => { if (cont[i.status] != null) cont[i.status]++; });
    const npsCor = nps.nps == null ? "#6B6A65" : (nps.nps >= 50 ? "#1a7a4a" : nps.nps >= 0 ? "#c97a00" : "#b3261e");
    const tipoLabel = t => (FB.TIPOS[t] ? FB.TIPOS[t].label : t);
    const fOpt = (cur, val, lbl) => `<option value="${val}"${cur === val ? " selected" : ""}>${lbl}</option>`;
    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:16px">
        <div><h2 class="page-title" style="margin:0">Voz do cliente</h2><p class="page-sub" style="margin:0">Avaliações, sugestões e problemas enviados no app · triagem ao vivo</p></div>
        <button class="btn" onclick="renderFeedback()"><i class="ti ti-refresh"></i>Atualizar</button>
      </div>
      <div class="grid grid-3" style="margin-bottom:14px">
        ${card2("NPS", nps.respostas ? String(nps.nps) : "—", npsCor)}
        ${card("Avaliações", fmt(nps.respostas))}
        ${card("Resultados", fmt(itens.length))}
        ${card2("Novos (a triar)", fmt(cont.novo), "#185FA5")}
      </div>
      <div class="fb-adm-filtros">
        <select id="fb-f-tipo" class="sinapi-uf" data-cbselect aria-label="Filtrar por tipo" onchange="fbAdmFiltro()"><option value="">Todos os tipos</option>${Object.keys(FB.TIPOS).map(t => fOpt(filtro.tipo, t, FB.TIPOS[t].label)).join("")}</select>
        <select id="fb-f-status" class="sinapi-uf" data-cbselect aria-label="Filtrar por status" onchange="fbAdmFiltro()"><option value="">Todos os status</option>${["novo", "em_analise", "planejado", "concluido"].map(s => fOpt(filtro.status, s, FB.STATUS[s][0])).join("")}</select>
      </div>
      <div id="fb-adm-lista">${listaErro ? `<div class="card"><p class="page-sub" style="margin:0">Erro ao carregar a lista (a migration 0018_feedback.sql foi aplicada?): ${escA(listaErro)}</p></div>` : (itens.length ? itens.map(i => fbAdmRow(i, tipoLabel, autores)).join("") : `<div class="card"><p class="page-sub" style="margin:0">Nenhum feedback ainda.</p></div>`)}</div>`;
  }
}
// e31 — rastreabilidade: QUAL (id curto, uuid inteiro no title p/ cruzar com suporte), QUEM
// (nome/e-mail pela RPC 0079; sem ela, o user_id curto — feedback é sempre autenticado, 0018) e
// QUANDO (data E HORA — created_at é timestamptz; antes a hora era truncada no toLocaleDateString).
function fbAdmRow(i, tipoLabel, autores) {
  const nota = i.tipo === "avaliacao" && i.nota != null ? `<span class="fb-adm-nota">${i.nota}/10</span>` : "";
  const stSel = ["novo", "em_analise", "planejado", "concluido"].map(s => `<option value="${s}"${i.status === s ? " selected" : ""}>${FB.STATUS[s][0]}</option>`).join("");
  const curto = u => String(u || "").slice(0, 8);
  const quando = i.created_at ? new Date(i.created_at).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }) : "—";
  const a = autores && autores.get ? autores.get(i.user_id) : null;
  const quem = a && (a.nome || a.email)
    ? `${escA(a.nome || a.email)}${a.nome && a.email ? ` <span style="color:var(--text-3)">&lt;${escA(a.email)}&gt;</span>` : ""}`
    : `<span title="user_id ${escA(i.user_id)} — aplique a migration 0079 p/ ver nome/e-mail">usuário ${escA(curto(i.user_id))}</span>`;
  return `<div class="card fb-adm-row">
    <div class="fb-adm-head">
      <span class="pill pill-gray">${escA(tipoLabel(i.tipo))}</span>${nota}
      <span class="fb-adm-meta">${escA(i.contexto || "—")} · ${escA(quando)}</span>
      ${i.promovido ? `<span class="pill pill-teal" title="Promovido ao roadmap/PLANO">promovido</span>` : ""}
    </div>
    <div class="fb-adm-meta" style="margin:2px 0 6px;font-size:12px">
      <i class="ti ti-user"></i> ${quem}
      · <span title="feedback ${escA(i.id)}" style="font-family:ui-monospace,monospace">#${escA(curto(i.id))}</span>
      · <span title="user_id ${escA(i.user_id)}" style="font-family:ui-monospace,monospace">u:${escA(curto(i.user_id))}</span>
    </div>
    ${i.texto ? `<div class="fb-adm-txt">${escA(i.texto)}</div>` : `<div class="fb-adm-txt" style="color:var(--text-3)">— sem comentário —</div>`}
    <div class="fb-adm-acoes">
      <select class="sinapi-uf" data-cbselect aria-label="Mudar status" onchange="fbAdmStatus('${i.id}', this.value)" title="Mudar status">${stSel}</select>
      <button class="btn sm" onclick="fbAdmPromover('${i.id}', ${i.promovido ? "false" : "true"})"><i class="ti ti-rocket"></i>${i.promovido ? "Despromover" : "Promover"}</button>
    </div>
  </div>`;
}
function fbAdmFiltro() {
  renderFeedback._filtro = { tipo: (document.getElementById("fb-f-tipo") || {}).value || "", status: (document.getElementById("fb-f-status") || {}).value || "" };
  renderFeedback();
}
async function fbAdmStatus(id, status) {
  try { await FB.atualizarStatus(id, status); toast("Status atualizado para “" + (FB.STATUS[status] ? FB.STATUS[status][0] : status) + "”.", "success"); }
  catch (e) { toast("Erro: " + (e.message || e), "error"); }
}
async function fbAdmPromover(id, val) {
  try { await FB.promover(id, val); toast(val ? "Promovido ao roadmap/PLANO." : "Promoção removida.", "success"); renderFeedback(); }
  catch (e) { toast("Erro: " + (e.message || e), "error"); }
}

// ── f45: follow-up por dados + utilidade ──────────────────────────────────
// O painel é honesto sobre o cold start: enquanto o padrão não tiver suporte, ele DIZ que o
// assessor está calado e quanto falta — em vez de mostrar um gráfico vazio que parece defeito.
const FOLLOWUP_MIN_N = 20;   // espelha WA_FOLLOWUP_MIN_N do webhook (_shared/temas.ts)

async function painelFollowUp() {
  let seq = [], fb = [];
  try {
    const [s, f] = await Promise.all([
      window.supa.from("ia_temas_seq").select("tema_anterior,tema_seguinte,n").order("n", { ascending: false }).limit(12),
      window.supa.from("ia_feedback").select("sinal,tema"),
    ]);
    if (s.error || f.error) throw (s.error || f.error);
    seq = s.data || []; fb = f.data || [];
  } catch (e) {
    return `<div class="card" style="margin-top:14px"><h3 style="margin-bottom:8px">Follow-up e utilidade (f45)</h3>
      <p class="page-sub" style="margin:0">Tabelas ainda não criadas. Rode a migration <code>0058_temas_feedback.sql</code> no Supabase.</p></div>`;
  }

  const maxN = Math.max(1, ...seq.map(x => x.n));
  const prontos = seq.filter(x => x.n >= FOLLOWUP_MIN_N).length;

  // Utilidade por tema: positivos / total. Sem sinal, não inventa 0% (que leria como "ruim").
  const porTema = {};
  fb.forEach(r => {
    const k = r.tema || "(sem tema)";
    porTema[k] = porTema[k] || { pos: 0, tot: 0 };
    porTema[k].tot++; if (r.sinal === "positivo") porTema[k].pos++;
  });
  const temas = Object.entries(porTema).sort((a, b) => b[1].tot - a[1].tot).slice(0, 10);

  return `
    <div class="grid grid-2" style="margin-top:14px;align-items:start">
      <div class="card">
        <h3 style="margin-bottom:4px">Sequência de temas (f45)</h3>
        <p class="page-sub" style="margin:0 0 12px;font-size:12px">O que os usuários perguntam <strong>depois</strong> de cada tema. A sugestão só é oferecida a partir de <strong>${FOLLOWUP_MIN_N}</strong> ocorrências do par.</p>
        ${seq.length ? `
          <p style="font-size:13px;margin:0 0 10px;color:${prontos ? "var(--teal)" : "var(--text-2)"}">
            <i class="ti ti-${prontos ? "circle-check" : "clock"}"></i>
            ${prontos ? `${prontos} par(es) com suporte suficiente — o assessor já sugere nesses casos.` : `Nenhum par atingiu o mínimo ainda: o assessor está <strong>calado</strong>, como deve ser sem dados.`}
          </p>
          ${seq.map(x => `
            <div style="margin-bottom:10px">
              <div style="display:flex;justify-content:space-between;gap:8px;font-size:12.5px;margin-bottom:3px">
                <span>${escA(x.tema_anterior)} <i class="ti ti-arrow-right" style="color:var(--text-3)"></i> ${escA(x.tema_seguinte)}</span>
                <span style="color:var(--text-2)">${fmt(x.n)}${x.n >= FOLLOWUP_MIN_N ? " ✓" : ""}</span>
              </div>
              <div style="height:7px;background:var(--bg);border-radius:99px;overflow:hidden">
                <div style="height:100%;width:${Math.round(x.n / maxN * 100)}%;background:var(--${x.n >= FOLLOWUP_MIN_N ? "teal" : "blue"});border-radius:99px"></div>
              </div>
            </div>`).join("")}`
        : `<p class="page-sub" style="margin:0">Ainda sem sequências registradas. Elas se acumulam sozinhas conforme o WhatsApp é usado — <strong>não há nada a fazer aqui</strong>, só esperar o uso.</p>`}
      </div>

      <div class="card">
        <h3 style="margin-bottom:4px">Utilidade por tema (f45)</h3>
        <p class="page-sub" style="margin:0 0 12px;font-size:12px">Reações 👍/👎 na resposta e "obrigado" — sem perguntar nada ao usuário.</p>
        ${temas.length ? `
          <table class="spec-table">
            ${temas.map(([t, v]) => `<tr><td>${escA(t)}</td><td style="text-align:right">${Math.round(v.pos / v.tot * 100)}% útil <span style="color:var(--text-3)">(${v.tot})</span></td></tr>`).join("")}
          </table>`
        : `<p class="page-sub" style="margin:0">Nenhum sinal ainda. Um 👍 na resposta dentro do WhatsApp já conta.</p>`}
      </div>
    </div>`;
}

// ── f46 (fatia 1): telemetria do assessor — rótulos, nunca texto ──────────
// Lê ia_interacoes (0087): canal, tema (f41), abstenção (retrieval vazio), ferramenta (f39) e
// latência, gravados pelo _shared/assessor.ts. A ABSTENÇÃO POR TEMA é o dado que vira pauta de
// curadoria (f43): onde a base é fraca. Volume por interação de IA é baixo (cota mensal segura);
// se um dia crescer, o caminho é RPC de agregação como a insights_uso_agregado (a16).
async function painelTelemetria() {
  let rows = [];
  try {
    const desde = new Date(Date.now() - 14 * 86400000).toISOString();
    const { data, error } = await window.supa.from("ia_interacoes")
      .select("canal,tema,abstencao,ferramenta,ms").gte("criado_em", desde).limit(5000);
    if (error) throw error;
    rows = data || [];
  } catch (e) {
    return `<div class="card" style="margin-top:14px"><h3 style="margin-bottom:8px">Assessor — telemetria (f46)</h3>
      <p class="page-sub" style="margin:0">Tabela ainda não criada. Rode a migration <code>0087_ia_interacoes.sql</code> no Supabase (e redeploye as funções de IA).</p></div>`;
  }
  if (!rows.length) {
    return `<div class="card" style="margin-top:14px"><h3 style="margin-bottom:8px">Assessor — telemetria (f46)</h3>
      <p class="page-sub" style="margin:0">Nenhuma interação nos últimos 14 dias (ou o deploy com a telemetria ainda não aconteceu). Acumula sozinha com o uso — só rótulos, nunca o texto da conversa.</p></div>`;
  }
  const n = rows.length;
  const porCanal = { app: 0, whatsapp: 0 };
  rows.forEach(r => { if (porCanal[r.canal] != null) porCanal[r.canal]++; });
  const absTotal = rows.filter(r => r.abstencao).length;
  const comMs = rows.filter(r => Number.isFinite(r.ms)).map(r => r.ms).sort((a, b) => a - b);
  const msMed = comMs.length ? Math.round(comMs.reduce((s, x) => s + x, 0) / comMs.length) : null;
  const msP90 = comMs.length ? comMs[Math.min(comMs.length - 1, Math.floor(comMs.length * 0.9))] : null;
  const porTema = {};
  rows.forEach(r => {
    const t = r.tema || "(sem sinal)";
    porTema[t] = porTema[t] || { tot: 0, abs: 0 };
    porTema[t].tot++; if (r.abstencao) porTema[t].abs++;
  });
  const temas = Object.entries(porTema).sort((a, b) => b[1].tot - a[1].tot).slice(0, 6);
  const porFerr = {};
  rows.forEach(r => { if (r.ferramenta) String(r.ferramenta).split("+").forEach(f => porFerr[f] = (porFerr[f] || 0) + 1); });
  const ferrs = Object.entries(porFerr).sort((a, b) => b[1] - a[1]).slice(0, 5);
  return `<div class="card" style="margin-top:14px">
    <h3 style="margin-bottom:4px">Assessor — telemetria (f46)</h3>
    <p class="page-sub" style="margin:0 0 12px;font-size:12px">Últimos 14 dias, só rótulos (LGPD como no f45). A <strong>abstenção por tema</strong> é a pauta de curadoria: onde a base não soube responder.</p>
    <div class="grid grid-3" style="margin-bottom:10px">
      <div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800">${fmt(n)}</div><div class="page-sub" style="margin:0;font-size:12px">interações · app ${fmt(porCanal.app)} × zap ${fmt(porCanal.whatsapp)}</div></div>
      <div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800;color:${absTotal ? "var(--amber)" : "inherit"}">${Math.round(absTotal / n * 100)}%</div><div class="page-sub" style="margin:0;font-size:12px">abstenção (${fmt(absTotal)} de ${fmt(n)})</div></div>
      <div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800">${msMed != null ? (msMed / 1000).toFixed(1) + "s" : "—"}</div><div class="page-sub" style="margin:0;font-size:12px">latência média · p90 ${msP90 != null ? (msP90 / 1000).toFixed(1) + "s" : "—"}</div></div>
    </div>
    ${temas.length ? `<table class="spec-table">
      ${temas.map(([t, v]) => `<tr><td>${escA(t)}</td><td style="text-align:right">${fmt(v.tot)} interação(ões) · <span style="color:${v.abs ? "var(--amber)" : "var(--text-3)"}">${Math.round(v.abs / v.tot * 100)}% abstenção</span></td></tr>`).join("")}
    </table>` : ""}
    ${ferrs.length ? `<p class="page-sub" style="margin:10px 0 0;font-size:12px"><strong>Ferramentas (f39):</strong> ${ferrs.map(([f, c]) => `${escA(f)} (${fmt(c)})`).join(" · ")}</p>` : ""}
  </div>`;
}

// ── Métricas ──────────────────────────────────────────────────────────────
async function renderAdmin() {
  setActiveTab("metricas");
  const el = adminEl();
  el.classList.remove("adm-body--embed");
  el.innerHTML = `<div class="grid grid-3">${'<div class="card" style="text-align:center"><div class="skel" style="height:13px;width:60%;margin:0 auto 10px"></div><div class="skel" style="height:28px;width:40%;margin:0 auto"></div></div>'.repeat(6)}</div>`;
  try {
    const [ov, mods, planos, conselhos, users] = await Promise.all([
      window.supa.from("v_metrics_overview").select("*").single(),
      window.supa.from("v_events_by_module").select("*"),
      window.supa.from("v_plan_distribution").select("*"),
      window.supa.from("v_conselho_distribution").select("*"),
      window.supa.from("v_user_usage").select("*").order("minutos_30d", { ascending: false }).limit(100)
    ]);
    if (ov.error) throw ov.error;
    const o = ov.data || {};
    const maxEv = Math.max(1, ...((mods.data || []).map(m => m.eventos)));
    const maxConselho = Math.max(1, ...((conselhos.data || []).map(c => c.usuarios)));

    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:18px">
        <div>
          <h2 class="page-title" style="margin:0">Métricas do Civilbook</h2>
          <p class="page-sub" style="margin:0">Visão dos últimos 30 dias · dados ao vivo do Supabase</p>
        </div>
        <button class="btn" onclick="renderAdmin()"><i class="ti ti-refresh"></i>Atualizar</button>
      </div>

      <div class="grid grid-3" style="margin-bottom:8px">
        ${card("Usuários totais", fmt(o.total_usuarios))}
        ${card("Ativos (7 dias)", fmt(o.ativos_7d))}
        ${card("Ativos (30 dias)", fmt(o.ativos_30d))}
        ${card("Novos (30 dias)", fmt(o.novos_30d))}
        ${card("Sessões (30 dias)", fmt(o.sessoes_30d))}
        ${card("Tempo médio/sessão", fmt(o.duracao_media_min_30d) + " min")}
      </div>

      <div class="grid grid-2" style="margin-top:14px;align-items:start">
        <div class="card">
          <h3 style="margin-bottom:12px">Eventos por módulo (30d)</h3>
          ${(mods.data || []).length ? (mods.data || []).map(m => `
            <div style="margin-bottom:10px">
              <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:3px">
                <span>${escA(m.module)}</span>
                <span style="color:var(--text-2)">${fmt(m.eventos)} · ${fmt(m.usuarios)} usr</span>
              </div>
              <div style="height:7px;background:var(--bg);border-radius:99px;overflow:hidden">
                <div style="height:100%;width:${Math.round(m.eventos / maxEv * 100)}%;background:var(--blue);border-radius:99px"></div>
              </div>
            </div>`).join("") : `<p class="page-sub">Sem eventos ainda.</p>`}
        </div>

        <div style="display:flex;flex-direction:column;gap:14px">
          <div class="card">
            <h3 style="margin-bottom:12px">Distribuição de planos</h3>
            <table class="spec-table">
              ${(planos.data || []).map(p => `<tr><td>${escA(p.plano)}</td><td>${fmt(p.usuarios)} usuário(s)</td></tr>`).join("")}
            </table>
          </div>

          <div class="card">
            <h3 style="margin-bottom:12px">Usuários por conselho</h3>
            ${(conselhos.data || []).length ? (conselhos.data || []).map(c => `
              <div style="margin-bottom:10px">
                <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:3px">
                  <span>${escA(c.conselho)}</span>
                  <span style="color:var(--text-2)">${fmt(c.usuarios)} usr</span>
                </div>
                <div style="height:7px;background:var(--bg);border-radius:99px;overflow:hidden">
                  <div style="height:100%;width:${Math.round(c.usuarios / maxConselho * 100)}%;background:${conselhoCor(c.conselho)};border-radius:99px"></div>
                </div>
              </div>`).join("") : `<p class="page-sub">Sem dados de conselho. Rode a migration <code>0005_conselho_view.sql</code> no Supabase.</p>`}
          </div>
        </div>
      </div>

      ${await insightsCardHTML()}

      ${await painelFollowUp()}
      ${await painelTelemetria()}

      <div class="card" style="margin-top:14px">
        <h3 style="margin-bottom:12px">Uso por usuário (30d) — top 100</h3>
        <div style="overflow-x:auto">
          <table class="data">
            <thead><tr><th>Usuário</th><th>E-mail</th><th>Plano</th><th style="text-align:right">Sessões</th><th style="text-align:right">Minutos</th><th>Última atividade</th></tr></thead>
            <tbody>
              ${(users.data || []).map(u => `
                <tr>
                  <td>${escA(u.nome) || "—"}</td>
                  <td>${escA(u.email) || "—"}</td>
                  <td>${escA(u.plano)}</td>
                  <td style="text-align:right">${fmt(u.sessoes_30d)}</td>
                  <td style="text-align:right">${fmt(u.minutos_30d)}</td>
                  <td>${u.ultima_atividade ? new Date(u.ultima_atividade).toLocaleString("pt-BR") : "—"}</td>
                </tr>`).join("") || `<tr><td colspan="6" style="color:var(--text-3)">Sem dados.</td></tr>`}
            </tbody>
          </table>
        </div>
      </div>`;
  } catch (e) {
    el.innerHTML = `<div class="card"><p style="color:var(--red)">Erro ao carregar métricas: ${escA(e.message || e)}</p>
      <p class="page-sub">Confirme que você está logado em uma conta com <code>role = 'admin'</code> e que as views foram criadas (0002_views.sql).</p></div>`;
  }
}

function card(label, valor) {
  return `<div class="card" style="text-align:center">
    <div style="font-size:13px;color:var(--text-2)">${label}</div>
    <div style="font-size:30px;font-weight:600;color:var(--blue);margin-top:4px">${valor}</div>
  </div>`;
}

// Cor por conselho profissional (barras da distribuição de usuários).
function conselhoCor(nome) {
  return {
    "CREA": "#185FA5",       // azul — engenharia
    "CAU": "#7c3aed",        // roxo — arquitetura
    "CFT": "#0e9488",        // teal — técnicos
    "Outro": "#c97a00",      // âmbar
    "Estudante": "#1a7a4a",  // verde
  }[nome] || "var(--text-3)"; // cinza — "Não informado" / desconhecido
}

// ── Marketing & aquisição ──────────────────────────────────────────────────
// Barra horizontal reutilizável (rótulo + valor à direita + barra proporcional ao máximo).
function admBar(label, n, max, cor, right) {
  return `<div style="margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:3px">
      <span>${escA(label)}</span><span style="color:var(--text-2)">${right != null ? right : fmt(n)}</span>
    </div>
    <div style="height:7px;background:var(--bg);border-radius:99px;overflow:hidden">
      <div style="height:100%;width:${Math.max(2, Math.round((n / (max || 1)) * 100))}%;background:${cor};border-radius:99px"></div>
    </div>
  </div>`;
}

async function renderMarketing() {
  setActiveTab("marketing");
  const el = adminEl();
  el.classList.remove("adm-body--embed");
  el.innerHTML = `<div class="grid grid-3">${'<div class="card" style="text-align:center"><div class="skel" style="height:13px;width:60%;margin:0 auto 10px"></div><div class="skel" style="height:28px;width:40%;margin:0 auto"></div></div>'.repeat(6)}</div>`;
  try {
    const [funil, origem, campanhas, mensal, planos, nps] = await Promise.all([
      window.supa.from("v_marketing_funnel").select("*").single(),
      window.supa.from("v_leads_por_origem").select("*"),
      window.supa.from("v_leads_por_campanha").select("*"),
      window.supa.from("v_leads_mensal").select("*"),
      window.supa.from("v_plan_distribution").select("*"),
      (typeof FB !== "undefined" ? FB.npsResumo().catch(() => ({ respostas: 0, nps: null })) : Promise.resolve({ respostas: 0, nps: null }))
    ]);
    if (funil.error) throw funil.error;
    const f = funil.data || {};
    const og = origem.data || [], camp = campanhas.data || [], mes = mensal.data || [], pl = planos.data || [];

    const convPro = f.cadastros_total ? Math.round((f.assinantes_pro / f.cadastros_total) * 100) : 0;
    const convAtivo = f.cadastros_total ? Math.round((f.ativos_30d / f.cadastros_total) * 100) : 0;

    // Funil de aquisição (sequencial: cada etapa é subconjunto da anterior → conversões ≤ 100%).
    const etapas = [
      { nome: "Cadastros (contas)", n: f.cadastros_total || 0, cor: "#185FA5" },
      { nome: "Usuários ativos (30d)", n: f.ativos_30d || 0, cor: "#0e9488" },
      { nome: "Assinantes PRO", n: f.assinantes_pro || 0, cor: "#1a7a4a" }
    ];
    const maxEtapa = Math.max(1, ...etapas.map(e => e.n));
    const funilHTML = etapas.map((e, i) => {
      const prev = i ? etapas[i - 1].n : 0;
      const taxa = i && prev ? ` · ${Math.round((e.n / prev) * 100)}%` : "";
      return admBar(e.nome, e.n, maxEtapa, e.cor, fmt(e.n) + taxa);
    }).join("");

    const maxOrigem = Math.max(1, ...og.map(o => o.leads));
    const maxMes = Math.max(1, ...mes.map(m => m.leads));
    const maxPlano = Math.max(1, ...pl.map(x => x.usuarios));
    const totalPl = pl.reduce((s, p) => s + Number(p.usuarios || 0), 0);
    const planoCor = p => (p === "pro" ? "#1a7a4a" : p === "gratuito" ? "#185FA5" : "#c97a00");

    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:18px">
        <div>
          <h2 class="page-title" style="margin:0">Marketing & aquisição</h2>
          <p class="page-sub" style="margin:0">Funil, origem dos leads e conversão · dados ao vivo do Supabase</p>
        </div>
        <button class="btn" onclick="renderMarketing()"><i class="ti ti-refresh"></i>Atualizar</button>
      </div>

      <div class="grid grid-3" style="margin-bottom:8px">
        ${card("Leads (orçamentos)", fmt(f.leads_total))}
        ${card("Leads (30 dias)", fmt(f.leads_30d))}
        ${card("Cadastros", fmt(f.cadastros_total))}
        ${card("Assinantes PRO", fmt(f.assinantes_pro))}
        ${card2("Conversão p/ PRO", convPro + "%", "#1a7a4a")}
        ${card2("Ativação (30d)", convAtivo + "%", "#0e9488")}
        ${card2("NPS (voz do cliente)", nps.respostas ? String(nps.nps) : "—", nps.nps == null ? "#6B6A65" : (nps.nps >= 50 ? "#1a7a4a" : nps.nps >= 0 ? "#c97a00" : "#b3261e"))}
      </div>

      <div class="card" style="margin-top:14px" id="precos-painel"><p class="page-sub" style="margin:0">Carregando preços do plano…</p></div>

      <div class="grid grid-2" style="margin-top:14px;align-items:start">
        <div class="card">
          <h3 style="margin-bottom:4px">Funil de aquisição</h3>
          <p class="page-sub" style="margin:0 0 12px">Da conta criada à assinatura PRO (% sobre a etapa anterior).</p>
          ${funilHTML}
        </div>
        <div class="card">
          <h3 style="margin-bottom:12px">Origem dos leads</h3>
          ${og.length ? og.map(o => admBar(o.origem, o.leads, maxOrigem, "#185FA5", fmt(o.leads))).join("") : `<p class="page-sub">Sem leads ainda.</p>`}
        </div>
      </div>

      <div class="grid grid-2" style="margin-top:14px;align-items:start">
        <div class="card">
          <h3 style="margin-bottom:12px">Conversão por plano</h3>
          ${pl.length ? pl.map(p => admBar(p.plano, p.usuarios, maxPlano, planoCor(p.plano), `${fmt(p.usuarios)} · ${totalPl ? Math.round(p.usuarios / totalPl * 100) : 0}%`)).join("") : `<p class="page-sub">Sem dados de plano.</p>`}
        </div>
        <div class="card">
          <h3 style="margin-bottom:12px">Leads por mês</h3>
          ${mes.length ? mes.map(m => admBar(m.mes, m.leads, maxMes, "#0e9488", fmt(m.leads))).join("") : `<p class="page-sub">Sem leads nos últimos meses.</p>`}
        </div>
      </div>

      <div class="card" style="margin-top:14px">
        <h3 style="margin-bottom:12px">Desempenho de campanhas</h3>
        <div style="overflow-x:auto">
          <table class="data">
            <thead><tr><th>Campanha (utm_campaign)</th><th style="text-align:right">Leads</th><th>Último lead</th></tr></thead>
            <tbody>
              ${camp.length ? camp.map(c => `<tr>
                <td>${escA(c.campanha)}</td>
                <td style="text-align:right">${fmt(c.leads)}</td>
                <td>${c.ultimo ? new Date(c.ultimo).toLocaleDateString("pt-BR") : "—"}</td>
              </tr>`).join("") : `<tr><td colspan="3" style="color:var(--text-3)">Sem campanhas marcadas. Use links com <code>?utm_source=…&utm_campaign=…</code> para medir o desempenho.</td></tr>`}
            </tbody>
          </table>
        </div>
      </div>

      <div class="card" style="margin-top:14px">
        <h3 style="margin-bottom:4px"><i class="ti ti-link"></i> Gerador de links UTM</h3>
        <div id="utm-builder"></div>
      </div>

      <div class="card" style="margin-top:14px" id="leads-retencao">
        <h3 style="margin-bottom:4px"><i class="ti ti-trash"></i> Retenção de leads (LGPD)</h3>
        <p class="page-sub" style="margin:0 0 8px">Leads são dados pessoais de visitantes. Expurgar os frios cumpre o término do tratamento (art. 15/16). Ver <code>docs/AUDITORIA-SEGURANCA-2026-08.md</code> (L7).</p>
        <p class="page-sub" style="margin:0">Carregando…</p>
      </div>
      <p class="page-sub" style="margin-top:14px"><i class="ti ti-info-circle"></i> Origem e campanha vêm da atribuição (utm_*) capturada no formulário de orçamento. Leads antigos aparecem como "Direto / não informado".</p>`;
    montarUTM("utm-builder");
    renderPrecosPainel();
    renderLeadsRetencao();
  } catch (e) {
    el.innerHTML = `<div class="card"><p style="color:var(--red)">Erro ao carregar o painel de marketing: ${escA(e.message || e)}</p>
      <p class="page-sub">Confirme que você é <code>admin</code> e que a migration <code>0013_marketing.sql</code> foi aplicada no Supabase.</p></div>`;
  }
}

// L7: retenção de leads. Mostra quantos leads frios (> N meses) existem e permite expurgar.
// Usa as RPCs admin-only leads_frios_contagem/leads_expurgar (0066, gate is_admin).
let _leadsMeses = 18;
async function renderLeadsRetencao() {
  const host = document.getElementById("leads-retencao");
  if (!host || !window.supa) return;
  const base = `<h3 style="margin-bottom:4px"><i class="ti ti-trash"></i> Retenção de leads (LGPD)</h3>
    <p class="page-sub" style="margin:0 0 8px">Leads são dados pessoais de visitantes. Expurgar os frios cumpre o término do tratamento (art. 15/16). Ver <code>docs/AUDITORIA-SEGURANCA-2026-08.md</code> (L7).</p>`;
  let n = null, erro = null;
  try {
    const { data, error } = await window.supa.rpc("leads_frios_contagem", { p_meses: _leadsMeses });
    if (error) throw error; n = data || 0;
  } catch (e) { erro = e.message || String(e); }
  if (erro) {
    host.innerHTML = base + `<p class="page-sub" style="margin:0">Aplique a migration <code>0066_leads_expurgo.sql</code> para habilitar o expurgo.</p>`;
    return;
  }
  host.innerHTML = base + `
    <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
      <label style="font-size:13px;display:flex;align-items:center;gap:6px">Frios há mais de
        <select id="leads-meses" class="sinapi-uf" style="width:auto" onchange="leadsMudarMeses(this.value)">
          ${[12, 18, 24, 36].map(m => `<option value="${m}"${m === _leadsMeses ? " selected" : ""}>${m} meses</option>`).join("")}
        </select>
      </label>
      <span style="font-size:14px"><strong>${fmt(n)}</strong> lead(s) a expurgar</span>
      ${n > 0 ? `<button class="btn" style="color:var(--red);border-color:var(--red)" onclick="leadsExpurgar()"><i class="ti ti-trash"></i> Expurgar ${fmt(n)} agora</button>` : `<span class="page-sub" style="margin:0;color:#1a7a4a">nada a expurgar</span>`}
    </div>`;
}
function leadsMudarMeses(v) { _leadsMeses = parseInt(v, 10) || 18; renderLeadsRetencao(); }
async function leadsExpurgar() {
  if (!await cbConfirmar(`Expurgar definitivamente os leads frios há mais de ${_leadsMeses} meses?\n\nApaga nome, e-mail e telefone desses contatos. Não há como desfazer.`)) return;
  try {
    const { data, error } = await window.supa.rpc("leads_expurgar", { p_meses: _leadsMeses });
    if (error) throw error;
    toast(`${data || 0} lead(s) expurgado(s).`, "success");
    renderLeadsRetencao();
  } catch (e) { toast("Erro ao expurgar: " + (e.message || e), "error"); }
}

// ── Gerador de UTM (d8) ─────────────────────────────────────────────────────
// Monta links de divulgação padronizados (nunca o link "limpo"): utm_source/medium/campaign
// (+ content/term opcionais), normalizados (minúsculas, espaços→"-") e codificados. Os mesmos
// utm_* são capturados como atribuição no lead (e5) e lidos pelo GA4 → "qual canal/campanha converte".
function montarUTM(containerId) {
  const el = document.getElementById(containerId);
  if (!el) return;
  const sources = ["google", "facebook", "instagram", "tiktok", "linkedin", "youtube", "email", "whatsapp", "bio"];
  const mediums = ["cpc", "social", "email", "organic", "referral", "display", "affiliate", "push"];
  el.innerHTML = `
    <p class="page-sub" style="margin:0 0 12px">Use sempre links etiquetados. Os parâmetros alimentam <em>Origem dos leads</em> e <em>Campanhas</em> acima, além do GA4.</p>
    <div class="grid grid-2" style="gap:10px">
      <div class="field"><label>URL base</label><input id="utm-url" value="https://civilbook.com.br/"></div>
      <div class="field"><label>utm_campaign</label><input id="utm-campaign" placeholder="ex.: lancamento-junho"></div>
      <div class="field"><label>utm_source</label><input id="utm-source" list="utm-srcs" placeholder="ex.: instagram"><datalist id="utm-srcs">${sources.map(s => `<option value="${s}">`).join("")}</datalist></div>
      <div class="field"><label>utm_medium</label><input id="utm-medium" list="utm-meds" placeholder="ex.: social"><datalist id="utm-meds">${mediums.map(s => `<option value="${s}">`).join("")}</datalist></div>
      <div class="field"><label>utm_content (opcional)</label><input id="utm-content" placeholder="ex.: story-01"></div>
      <div class="field"><label>utm_term (opcional)</label><input id="utm-term" placeholder="ex.: gestao-manutencao"></div>
    </div>
    <div class="field"><label>Link gerado</label><input id="utm-out" readonly onclick="this.select()" style="font-family:monospace;font-size:13px"></div>
    <button class="btn primary" id="utm-copy"><i class="ti ti-copy"></i>Copiar link</button>`;
  // minúsculas + remove acentos (NFD, filtrando os diacríticos 768–879 sem regex literal) + espaços→"-"
  const norm = v => (v || "").trim().toLowerCase().normalize("NFD")
    .split("").filter(c => { const n = c.charCodeAt(0); return n < 768 || n > 879; }).join("").replace(/\s+/g, "-");
  const build = () => {
    const base = (document.getElementById("utm-url").value || "").trim();
    if (!base) return "";
    const p = [];
    [["utm_source", "utm-source"], ["utm_medium", "utm-medium"], ["utm_campaign", "utm-campaign"], ["utm_content", "utm-content"], ["utm_term", "utm-term"]].forEach(pair => {
      const v = norm(document.getElementById(pair[1]).value);
      if (v) p.push(pair[0] + "=" + encodeURIComponent(v));
    });
    return p.length ? base + (base.indexOf("?") >= 0 ? "&" : "?") + p.join("&") : base;
  };
  const refresh = () => { document.getElementById("utm-out").value = build(); };
  el.querySelectorAll("input").forEach(i => i.addEventListener("input", refresh));
  el.querySelector("#utm-copy").onclick = () => {
    const out = build(); if (!out) return;
    navigator.clipboard.writeText(out); if (typeof toast === "function") toast("Link UTM copiado.", "success");
  };
  refresh();
}

