    ov.innerHTML = `<div class="card cb-modal-box" role="dialog" aria-modal="true" style="max-width:620px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><h3 style="margin:0;font-size:17px">Linha de base (orçado)</h3><button class="btn icon-only" aria-label="Fechar" onclick="this.closest('.cb-modal-ov').remove()"><i class="ti ti-x"></i></button></div>
      <p style="font-size:12px;color:var(--text-2);margin:0 0 12px">Congele aqui o cenário <strong>realista</strong> simulado na aba <strong>Viabilidade</strong>. O dashboard compara o realizado com estes alvos.</p>
      <div style="display:flex;gap:10px;flex-wrap:wrap">
        ${f("bl-receita", "Receita mensal", base.receita_mensal, "R$")}${f("bl-custo", "Custo mensal", base.custo_mensal, "R$")}${f("bl-margem", "Margem alvo", base.margem_alvo, "%")}
        ${f("bl-ebitda", "EBITDA alvo", base.ebitda_alvo, "R$")}${f("bl-pe", "Ponto de equilíbrio", base.ponto_equilibrio, "R$")}${f("bl-runway", "Runway", base.runway_meses, "meses")}
        ${f("bl-cac", "CAC", base.cac, "R$")}${f("bl-ltv", "LTV", base.ltv, "R$")}${f("bl-caixa", "Caixa atual", base.caixa, "R$")}
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:8px"><button class="btn" onclick="this.closest('.cb-modal-ov').remove()">Cancelar</button><button class="btn primary" id="bl-save"><i class="ti ti-device-floppy"></i>Congelar linha de base</button></div>
    </div>`;
