        <div class="field" style="margin:0"><label for="cp-plano">Plano</label><select id="cp-plano" onchange="concederPlanoTrocou()"><option value="pro-cortesia">PRO cortesia</option><option value="gratuito">Gratuito (encerrar a cortesia)</option></select></div>
