// ── Repositório documental (e19) — contratos/políticas com versão e vigência ──
let _repoDocId = null;
async function renderRepositorio() {
  setActiveTab("repositorio");
  const el = adminEl(); el.classList.remove("adm-body--embed");
  el.innerHTML = `<p class="page-sub">Carregando…</p>`;
  if (typeof REPO === "undefined" || !window.supa) { el.innerHTML = `<p class="page-sub">Backend indisponível.</p>`; return; }
  try {
    const docs = await REPO.documentos();
    if (_repoDocId && !docs.find(d => d.id === _repoDocId)) _repoDocId = null;
    if (!_repoDocId && docs.length) _repoDocId = docs[0].id;
    const sel = docs.find(d => d.id === _repoDocId) || null;
    const versoes = sel ? await REPO.versoes(sel.id) : [];
    el.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px">
        <div><h2 class="page-title" style="margin:0">Repositório documental</h2><p class="page-sub" style="margin:0">Contratos e políticas com versão, vigência e hash · fonte única das páginas públicas</p></div>
        <button class="btn sm primary" onclick="repoNovoDoc()"><i class="ti ti-plus"></i>Novo documento</button>
      </div>
      <div class="repo-cols">
        <div class="repo-list">${docs.length ? docs.map(d => repoDocRow(d)).join("") : `<p class="page-sub" style="margin:0">Nenhum documento. Crie Termos de Uso, Política de Privacidade, etc.</p>`}</div>
        <div class="repo-detail card">${sel ? repoDetalhe(sel, versoes) : `<p class="page-sub" style="margin:0">Selecione um documento à esquerda.</p>`}</div>
      </div>`;
    if (sel && sel.requer_aceite) { const vig = versoes.find(v => v.status === "vigente"); if (vig) REPO.aceitesContagem(vig.id).then(c => { const n = document.getElementById("repo-aceites"); if (n) n.textContent = c + (c === 1 ? " aceite" : " aceites"); }); }
  } catch (e) {
    el.innerHTML = `<div class="card"><p class="page-sub" style="margin:0">Erro (a migration 0021_repositorio.sql foi aplicada?): ${escA(e.message || e)}</p></div>`;
  }
}
function repoDocRow(d) {
  const ativo = d.id === _repoDocId;
  return `<div class="repo-doc${ativo ? " active" : ""}" onclick="repoSel('${d.id}')">
    <div class="repo-doc-tit">${escA(d.titulo)}</div>
    <div class="repo-doc-meta"><code>${escA(d.chave)}</code> ${d.publico ? '<span class="pill pill-teal">público</span>' : '<span class="pill pill-gray">interno</span>'}${d.requer_aceite ? ' <span class="pill pill-blue">aceite</span>' : ""}</div>
  </div>`;
}
function repoDetalhe(d, versoes) {
  const vig = versoes.find(v => v.status === "vigente");
  return `<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap;margin-bottom:10px">
      <div><h3 class="fin-h" style="margin:0">${escA(d.titulo)}</h3><div class="repo-doc-meta"><code>${escA(d.chave)}</code> · ${escA(REPO.TIPOS[d.tipo] || d.tipo)}${d.requer_aceite && vig ? ` · <span id="repo-aceites">…</span>` : ""}</div></div>
      <button class="btn sm primary" onclick="repoNovaVersao('${d.id}')"><i class="ti ti-plus"></i>Nova versão</button>
    </div>
    ${versoes.length ? `<div class="repo-vers">${versoes.map(v => repoVersaoRow(d, v)).join("")}</div>` : `<p class="page-sub" style="margin:0">Sem versões. Crie a primeira (começa como rascunho).</p>`}`;
}
function repoVersaoRow(d, v) {
  const st = REPO.STATUS[v.status] || [v.status, "pill-gray"];
  const dt = v.vigencia_inicio ? new Date(v.vigencia_inicio + "T00:00:00").toLocaleDateString("pt-BR") : "";
  const a = [];
  if (v.status === "rascunho") a.push(`<button class="btn sm" onclick="repoStatus('${v.id}','em_revisao')">→ Em revisão</button>`);
  if (v.status === "em_revisao") a.push(`<button class="btn sm" onclick="repoStatus('${v.id}','rascunho')">← Rascunho</button>`);
  if (v.status === "rascunho" || v.status === "em_revisao") a.push(`<button class="btn sm primary" onclick="repoPublicar('${d.id}','${v.id}')"><i class="ti ti-checkbox"></i>Publicar (vigente)</button>`);
  if (v.status === "vigente") a.push(`<button class="btn sm" onclick="repoStatus('${v.id}','arquivado')"><i class="ti ti-archive"></i>Arquivar</button>`);
  return `<div class="repo-ver">
    <div class="repo-ver-top"><span class="pill ${st[1]}">${st[0]}</span><strong>v${escA(v.versao)}</strong>${dt ? `<span class="repo-ver-dt">vigente desde ${dt}</span>` : ""}<button class="btn sm icon-only" style="margin-left:auto" title="Ver conteúdo" onclick="repoVer('${v.id}')"><i class="ti ti-eye"></i></button></div>
    ${v.changelog ? `<div class="repo-ver-log">${escA(v.changelog)}</div>` : ""}
    ${v.hash ? `<div class="repo-ver-hash" title="SHA-256 do conteúdo (integridade)">hash ${escA(v.hash.slice(0, 16))}…</div>` : ""}
    <div class="repo-ver-acoes">${a.join("")}</div>
  </div>`;
}
function repoSel(id) { _repoDocId = id; renderRepositorio(); }
async function repoStatus(id, status) { try { await REPO.mudarStatus(id, status); toast("Status atualizado.", "success"); renderRepositorio(); } catch (e) { toast("Erro: " + (e.message || e), "error"); } }
async function repoPublicar(docId, vId) {
  if (!await cbConfirmar("Publicar esta versão como VIGENTE? A vigente atual (se houver) será arquivada e as páginas públicas passam a mostrar esta.")) return;
  try { await REPO.publicar(docId, vId); toast("Versão publicada (vigente).", "success"); renderRepositorio(); } catch (e) { toast("Erro ao publicar: " + (e.message || e), "error"); }
}
async function repoVer(vId) {
  try {
    const { data, error } = await window.supa.from("repo_versoes").select("versao,conteudo,hash,changelog").eq("id", vId).single();
    if (error) throw error;
    document.querySelectorAll(".cb-modal-ov").forEach(e => e.remove());
    const ov = document.createElement("div"); ov.className = "cb-modal-ov"; ov.onclick = e => { if (e.target === ov) ov.remove(); };
    ov.innerHTML = `<div class="card cb-modal-box" role="dialog" aria-modal="true" style="max-width:680px;max-height:86vh;overflow:auto">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><h3 style="margin:0;font-size:17px">Conteúdo — v${escA(data.versao)}</h3><button class="btn icon-only" aria-label="Fechar" onclick="this.closest('.cb-modal-ov').remove()"><i class="ti ti-x"></i></button></div>
      ${data.changelog ? `<p class="repo-ver-log">${escA(data.changelog)}</p>` : ""}
      <div class="cont-corpo">${REPO.corpoHTML(data.conteudo)}</div>
      ${data.hash ? `<p class="repo-ver-hash" style="margin-top:10px">SHA-256: ${escA(data.hash)}</p>` : ""}
    </div>`;
    document.body.appendChild(ov);
  } catch (e) { toast("Erro: " + (e.message || e), "error"); }
}
function repoNovoDoc() {
  document.querySelectorAll(".cb-modal-ov").forEach(e => e.remove());
  const ov = document.createElement("div"); ov.className = "cb-modal-ov"; ov.onclick = e => { if (e.target === ov) ov.remove(); };
  ov.innerHTML = `<div class="card cb-modal-box" role="dialog" aria-modal="true" style="max-width:520px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><h3 style="margin:0;font-size:17px">Novo documento</h3><button class="btn icon-only" aria-label="Fechar" onclick="this.closest('.cb-modal-ov').remove()"><i class="ti ti-x"></i></button></div>
    <div class="field"><label>Título</label><input type="text" id="rd-titulo" maxlength="120" placeholder="Ex.: Política de Privacidade"></div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      <div class="field" style="flex:1;min-width:150px"><label>Chave (slug)</label><input type="text" id="rd-chave" maxlength="40" placeholder="privacidade"></div>
      <div class="field" style="width:200px"><label>Tipo</label><select id="rd-tipo" class="sinapi-uf" data-cbselect>${Object.keys(REPO.TIPOS).map(t => `<option value="${t}">${escA(REPO.TIPOS[t])}</option>`).join("")}</select></div>
    </div>
    <label class="rmp-toggle" style="margin-bottom:6px"><input type="checkbox" id="rd-publico"> Público (renderizado nas páginas públicas)</label><br>
    <label class="rmp-toggle"><input type="checkbox" id="rd-aceite"> Requer aceite (rastrear quem aceitou — termos/privacidade)</label>
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px"><button class="btn" onclick="this.closest('.cb-modal-ov').remove()">Cancelar</button><button class="btn primary" id="rd-save"><i class="ti ti-device-floppy"></i>Criar</button></div>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector("#rd-save").onclick = async () => {
    const titulo = (document.getElementById("rd-titulo").value || "").trim();
    const chave = (document.getElementById("rd-chave").value || "").trim().toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-+|-+$/g, "");
    if (!titulo || !chave) { toast("Informe título e chave.", "error"); return; }
    try {
      const d = await REPO.criarDocumento({ titulo, chave, tipo: document.getElementById("rd-tipo").value, publico: document.getElementById("rd-publico").checked, requer_aceite: document.getElementById("rd-aceite").checked });
      _repoDocId = d.id; ov.remove(); toast("Documento criado.", "success"); renderRepositorio();
    } catch (e) { toast("Erro ao criar (chave já existe?): " + (e.message || e), "error"); }
  };
}
function repoNovaVersao(docId) {
  document.querySelectorAll(".cb-modal-ov").forEach(e => e.remove());
  const ov = document.createElement("div"); ov.className = "cb-modal-ov"; ov.onclick = e => { if (e.target === ov) ov.remove(); };
  ov.innerHTML = `<div class="card cb-modal-box" role="dialog" aria-modal="true" style="max-width:680px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><h3 style="margin:0;font-size:17px">Nova versão</h3><button class="btn icon-only" aria-label="Fechar" onclick="this.closest('.cb-modal-ov').remove()"><i class="ti ti-x"></i></button></div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      <div class="field" style="width:140px"><label>Versão</label><input type="text" id="rv-versao" maxlength="20" placeholder="1.0"></div>
      <div class="field" style="flex:1;min-width:200px"><label>Changelog (o que mudou)</label><input type="text" id="rv-log" maxlength="800" placeholder="Ex.: ajuste da cláusula de retenção (LGPD)"></div>
    </div>
    <div class="field"><label>Conteúdo</label><textarea id="rv-conteudo" rows="12" placeholder="Texto do documento. Linha em branco separa parágrafos."></textarea></div>
    <p style="font-size:11px;color:var(--text-3);margin:-4px 0 8px"><i class="ti ti-hash"></i> Um hash SHA-256 do conteúdo é calculado e guardado (integridade/auditoria). Começa como rascunho — publique para virar vigente. Conteúdo VAZIO é válido: a página pública continua renderizando o HTML estático e o repositório guarda só a trilha (o padrão da v1.0 da Política).</p>
    <div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn" onclick="this.closest('.cb-modal-ov').remove()">Cancelar</button><button class="btn primary" id="rv-save"><i class="ti ti-device-floppy"></i>Criar versão</button></div>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector("#rv-save").onclick = async () => {
    const versao = (document.getElementById("rv-versao").value || "").trim();
    const conteudo = document.getElementById("rv-conteudo").value || "";
    if (!versao) { toast("Informe o número da versão.", "error"); return; }
    if (!conteudo.trim() && !await cbConfirmar("Sem conteúdo: a página pública continua renderizando o HTML estático e o repositório guarda só a trilha de versão/vigência/changelog (o padrão da v1.0 da Política). Criar assim?")) return;
    try { await REPO.criarVersao({ documento_id: docId, versao, conteudo, changelog: (document.getElementById("rv-log").value || "").trim() }); ov.remove(); toast("Versão criada (rascunho).", "success"); renderRepositorio(); }
    catch (e) { toast("Erro ao criar versão: " + (e.message || e), "error"); }
  };
}

// ── Preços do plano (d14) — fonte única: landing + checkout + Asaas ─────────
function renderPrecosPainel() {
  const el = document.getElementById("precos-painel"); if (!el || typeof PRECOS === "undefined") return;
  const lbl = { "pro-mensal": "PRO Mensal", "pro-anual": "PRO Anual" };
  PRECOS.listarAdmin().then(rows => {
    el.innerHTML = `
      <h3 style="margin:0 0 10px;font-size:15px"><i class="ti ti-cash"></i> Preços do plano <span class="rmp-hint">— fonte única: o que a landing/checkout exibem e o que o Asaas cobra</span></h3>
      <div class="grid grid-2">${rows.map(r => `
        <div class="repo-ver">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
            <strong>${escA(lbl[r.plano] || r.plano)}</strong>
            ${r.ativo ? '<span class="pill pill-teal">ativo</span>' : '<span class="pill pill-gray">inativo</span>'}
          </div>
          <div style="font-size:13px;color:var(--text-2);margin-top:6px">Exibição: <strong>${escA(r.prefixo)} ${escA(r.preco)}${escA(r.periodo || "")}</strong></div>
          ${r.nota ? `<div style="font-size:12px;color:var(--text-3)">${escA(r.nota)}</div>` : ""}
          <div style="font-size:12.5px;margin-top:6px">Cobrança Asaas: <strong>R$ ${Number(r.valor).toFixed(2)}</strong> · ${r.ciclo === "YEARLY" ? "anual" : "mensal"}</div>
          <div style="margin-top:8px"><button class="btn sm" onclick="precoEditar('${escA(r.plano)}')"><i class="ti ti-edit"></i>Editar</button></div>
        </div>`).join("")}</div>`;
  }).catch(e => { el.innerHTML = `<p class="page-sub" style="margin:0">Erro nos preços (a migration 0022_planos_precos.sql foi aplicada?): ${escA(e.message || e)}</p>`; });
}
async function precoEditar(plano) {
  let row;
  try { const rows = await PRECOS.listarAdmin(); row = rows.find(r => r.plano === plano); } catch (e) { toast("Erro: " + (e.message || e), "error"); return; }
  if (!row) return;
  const lbl = { "pro-mensal": "PRO Mensal", "pro-anual": "PRO Anual" }[plano] || plano;
  document.querySelectorAll(".cb-modal-ov").forEach(e => e.remove());
  const ov = document.createElement("div"); ov.className = "cb-modal-ov"; ov.onclick = e => { if (e.target === ov) ov.remove(); };
  ov.innerHTML = `<div class="card cb-modal-box" role="dialog" aria-modal="true" style="max-width:560px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><h3 style="margin:0;font-size:17px">Preço — ${escA(lbl)}</h3><button class="btn icon-only" aria-label="Fechar" onclick="this.closest('.cb-modal-ov').remove()"><i class="ti ti-x"></i></button></div>
    <p style="font-size:12px;color:var(--text-2);margin:0 0 12px">A <strong>exibição</strong> (landing/checkout) e o <strong>valor cobrado</strong> (Asaas) saem daqui — um lugar só.</p>
    <div style="display:flex;gap:10px;flex-wrap:wrap">
      <div class="field" style="width:120px"><label>Prefixo</label><input type="text" id="pp-prefixo" maxlength="12" value="${escA(row.prefixo)}" placeholder="R$"></div>
      <div class="field" style="width:120px"><label>Preço (texto)</label><input type="text" id="pp-preco" maxlength="16" value="${escA(row.preco)}" placeholder="0,00"></div>
      <div class="field" style="width:100px"><label>Período</label><input type="text" id="pp-periodo" maxlength="10" value="${escA(row.periodo || "")}" placeholder="/mês"></div>
    </div>
    <div class="field"><label>Nota (subtítulo do card)</label><input type="text" id="pp-nota" maxlength="120" value="${escA(row.nota || "")}"></div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end">
      <div class="field" style="width:150px"><label>Valor cobrado (R$)</label><input type="number" step="0.01" id="pp-valor" value="${Number(row.valor)}"></div>
      <div class="field" style="width:150px"><label>Ciclo</label><select id="pp-ciclo" class="sinapi-uf" data-cbselect><option value="MONTHLY"${row.ciclo === "MONTHLY" ? " selected" : ""}>Mensal</option><option value="YEARLY"${row.ciclo === "YEARLY" ? " selected" : ""}>Anual</option></select></div>
      <label class="rmp-toggle" style="margin-bottom:14px"><input type="checkbox" id="pp-ativo" ${row.ativo ? "checked" : ""}> Ativo</label>
    </div>
    <div class="field"><label>Descrição da cobrança (Asaas)</label><input type="text" id="pp-desc" maxlength="120" value="${escA(row.descricao || "")}"></div>
    <div style="display:flex;gap:8px;justify-content:flex-end"><button class="btn" onclick="this.closest('.cb-modal-ov').remove()">Cancelar</button><button class="btn primary" id="pp-save"><i class="ti ti-device-floppy"></i>Salvar</button></div>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector("#pp-save").onclick = async () => {
    const g = id => (document.getElementById(id).value || "").trim();
    const valor = parseFloat(document.getElementById("pp-valor").value);
    if (isNaN(valor) || valor < 0) { toast("Valor de cobrança inválido.", "error"); return; }
    if (!g("pp-preco")) { toast("Informe o preço de exibição.", "error"); return; }
    try {
      await PRECOS.salvar(plano, { prefixo: g("pp-prefixo"), preco: g("pp-preco"), periodo: g("pp-periodo"), nota: g("pp-nota"), valor: valor, ciclo: document.getElementById("pp-ciclo").value, descricao: g("pp-desc"), ativo: document.getElementById("pp-ativo").checked });
      ov.remove(); toast("Preço atualizado — vale para a landing, o checkout e a cobrança.", "success"); renderPrecosPainel();
    } catch (e) { toast("Erro ao salvar: " + (e.message || e), "error"); }
  };
}

function card2(label, valor, cor) {
  return `<div class="card" style="text-align:center">
    <div style="font-size:13px;color:var(--text-2)">${label}</div>
    <div style="font-size:30px;font-weight:600;color:${cor};margin-top:4px">${valor}</div>
  </div>`;
}
